        W("أمل", "verb", "to hope", "يأمل", "آمل أن تكون بخير.", "I hope you are well.", ["آمل", "تأمل", "يأمل", "نأمل"], level=B),
        W("نصح", "verb", "to advise", "ينصح", "أنصحك بهذا المطعم.", "I recommend this restaurant to you.", ["أنصح", "ينصح", "تنصح", "نصحني"], level=B),
        W("رأي", "noun", "opinion", "رأي", "في رأيي، هذه فكرة جيدة.", "In my opinion, this is a good idea.", ["آراء", "رأيي"], "m", level=B),
        W("بيئة", "noun", "environment", "البيئة", "يجب أن نحمي البيئة.", "We must protect the environment.", ["البيئة"], "f", level=B),
        W("نصيحة", "noun", "piece of advice", "نصيحة", "شكرًا على النصيحة.", "Thanks for the advice.", ["نصائح", "النصيحة"], "f", level=B),
        W("وجب", "verb", "must", "يجب", "يجب أن تنام أكثر.", "You must sleep more.", ["يجب"], level=B),
